# pella_tomlinson_depletion ----
## Setup ----
# Expected depletion next year from depletion P, catch C, growth rate r,
# carrying capacity K and shape m, with the parameters on the log scale.
next_depletion <- function(depletion, catch, growth_rate, carrying_capacity,
                           shape) {
  FIMS:::pella_tomlinson_depletion(
    depletion, catch, log(growth_rate), log(carrying_capacity), log(shape)
  )
}

## IO correctness ----
test_that("`pella_tomlinson_depletion()` works with correct inputs", {
  # By hand: 0.88 + 0.2 / (2 - 1) * 0.88 * (1 - 0.88) - 10 / 645 = 0.8856161.
  #' @description Test that `pella_tomlinson_depletion()` returns 0.8856161 for a depletion of 0.88, catch of 10, r of 0.2, K of 645 and m of 2.
  expect_equal(
    object = next_depletion(0.88, 10, 0.2, 645, 2),
    expected = 0.8856161,
    tolerance = 1e-7
  )
  # 0.6 + 0.3 / (3 - 1) * 0.6 * (1 - 0.6^2) - 5 / 200
  # = 0.6 + 0.0576 - 0.025 = 0.6326. StateSpaceSIR's GENERALIZED_LOGISTIC()
  # gives the same with N = 120, r_max = 0.3 / 2, z = 2 and K = 200:
  # (120 + 0.15 * 120 * (1 - 0.6^2) - 5) / 200 = 0.6326.
  #' @description Test that `pella_tomlinson_depletion()` returns 0.6326 for a depletion of 0.6, catch of 5, r of 0.3, K of 200 and m of 3, the generalized logistic with r_max = r / (m - 1) and z = m - 1.
  expect_equal(
    object = next_depletion(0.6, 5, 0.3, 200, 3),
    expected = 0.6326
  )
  # Shape below 1: r / (m - 1) and 1 - P^(m - 1) are both negative, so
  # production is positive. 0.88 + 0.2 / -0.5 * 0.88 * (1 - 0.88^-0.5) -
  # 10 / 645 = 0.8877294, also from StateSpaceSIR's GENERALIZED_LOGISTIC()
  # with r_max = -0.4 and z = -0.5.
  #' @description Test that `pella_tomlinson_depletion()` returns 0.8877294 for a shape of 0.5, below 1, as StateSpaceSIR does with r_max = r / (m - 1) and z = m - 1.
  expect_equal(
    object = next_depletion(0.88, 10, 0.2, 645, 0.5),
    expected = 0.8877294,
    tolerance = 1e-7
  )
})

test_that("`pella_tomlinson_depletion()` has its maximum production at MSY", {
  # Production, without catch, is next depletion minus depletion. It is
  # largest at depletion m^(-1 / (m - 1)): 0.5 for m = 2 and 1 / sqrt(3) for
  # m = 3, the root of StateSpaceSIR's 1 - (z + 1) * P^z with z = 2.
  production <- function(depletion, shape) {
    next_depletion(depletion, 0, 0.3, 200, shape) - depletion
  }
  #' @description Test that production peaks at a depletion of 0.5 for the Schaefer model (m = 2).
  expect_equal(
    object = stats::optimize(
      production, c(0, 1),
      shape = 2, maximum = TRUE, tol = 1e-10
    )[["maximum"]],
    expected = 0.5,
    tolerance = 1e-6
  )
  #' @description Test that production peaks at a depletion of 1 / sqrt(3) for m = 3.
  expect_equal(
    object = stats::optimize(
      production, c(0, 1),
      shape = 3, maximum = TRUE, tol = 1e-10
    )[["maximum"]],
    expected = 1 / sqrt(3),
    tolerance = 1e-6
  )
  # MSY is r / m * K * P_MSY: 0.3 / 2 * 200 * 0.5 = 15 for m = 2.
  #' @description Test that production at a depletion of 0.5 is MSY, r / m * K * 0.5 = 15, for r of 0.3, K of 200 and m of 2.
  expect_equal(
    object = production(0.5, 2) * 200,
    expected = 15
  )
})

## Edge handling ----
test_that("`pella_tomlinson_depletion()` returns correct outputs for edge cases", {
  #' @description Test that `pella_tomlinson_depletion()` keeps an unfished population with no catch at 1.
  expect_equal(
    object = next_depletion(1, 0, 0.3, 200, 2),
    expected = 1
  )
  # The floor at 0.001 is in the model (surplus_production()), not here:
  # 0.1 + 0.2 * 0.1 * 0.9 - 50 / 100 = -0.382.
  #' @description Test that `pella_tomlinson_depletion()` returns -0.382 when the catch is more than the biomass plus production.
  expect_equal(
    object = next_depletion(0.1, 50, 0.2, 100, 2),
    expected = -0.382
  )
})

